-- Reverse 000121: remove the WAF agent TLS key rule and give the five rows the
-- description and conditions they had before. The flag a user can edit on a
-- built-in is never written.

DELETE FROM trace_detection_rules WHERE built_in = true AND name = 'Downgrade verified WAF agent TLS key reads';
UPDATE trace_detection_rules SET description = 'systemd calls execve to start services. These are not process injection. Only for a process the agent verified as the systemd host binary (or its child before exec); the name alone is not enough. Applies only below HIGH severity; process names alone do not justify hiding sensitive observations.', conditions = '[{"field":"comm","op":"eq","value":"systemd"},{"field":"event_name","op":"eq","value":"execve"},{"field":"exe_verified","op":"eq","value":true},{"field":"severity","op":"lte","value":2}]'::jsonb WHERE built_in = true AND name = 'Suppress systemd service start execve';
UPDATE trace_detection_rules SET description = 'dockerd creating/managing network sockets is normal container networking. Only for a process the agent verified as the dockerd host binary; a process renamed to dockerd is kept. Applies only below HIGH severity; process names alone do not justify hiding sensitive observations.', conditions = '[{"field":"comm","op":"eq","value":"dockerd"},{"field":"category","op":"eq","value":"network"},{"field":"exe_verified","op":"eq","value":true},{"field":"severity","op":"lte","value":2}]'::jsonb WHERE built_in = true AND name = 'Suppress dockerd network management';
UPDATE trace_detection_rules SET description = 'sshd loads its own host keys on every connection. Reading /etc/ssh/* is the daemon doing its job. Only for a process the agent verified as the sshd host binary.', conditions = '[{"field":"comm","op":"eq","value":"sshd"},{"field":"parent_comm","op":"eq","value":"sshd"},{"field":"event_name","op":"eq","value":"openat"},{"field":"filename","op":"starts_with","value":"/etc/ssh/"},{"field":"exe_verified","op":"eq","value":true},{"field":"event_name","op":"eq","value":"openat"},{"field":"flags","op":"bit_none","value":579}]'::jsonb WHERE built_in = true AND name = 'Downgrade sshd host key reads';
UPDATE trace_detection_rules SET description = 'sshd reads the account database during authentication and session setup. Only for a process the agent verified as the sshd host binary: a process and parent renamed to sshd reading /etc/shadow stay HIGH.', conditions = '[{"field":"comm","op":"eq","value":"sshd"},{"field":"parent_comm","op":"eq","value":"sshd"},{"field":"event_name","op":"eq","value":"openat"},{"field":"filename","op":"in","value":["/etc/passwd","/etc/shadow","/etc/group","/etc/gshadow","/etc/nsswitch.conf"]},{"field":"exe_verified","op":"eq","value":true},{"field":"event_name","op":"eq","value":"openat"},{"field":"flags","op":"bit_none","value":579}]'::jsonb WHERE built_in = true AND name = 'Downgrade sshd account database reads';
UPDATE trace_detection_rules SET description = 'sshd-session and the systemd user-session setup read /etc/shadow through PAM (pam_unix account checks) on every login. Only for a process the kernel saw in the agent-verified protected set; any other reader keeps HIGH or is escalated.', conditions = '[{"field":"comm","op":"in","value":["sshd","sshd-session","sshd-auth","(systemd)","(sd-pam)"]},{"field":"event_name","op":"eq","value":"openat"},{"field":"filename","op":"in","value":["/etc/shadow","/etc/gshadow"]},{"field":"exe_verified","op":"eq","value":true},{"field":"event_name","op":"eq","value":"openat"},{"field":"flags","op":"bit_none","value":579}]'::jsonb WHERE built_in = true AND name = 'Downgrade verified auth daemon account database reads';
